module.exports = "<!doctype html>\r\n<html lang=\"pt-BR\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<meta name=\"theme-color\" content=\"#111111\">\r\n<title>Neo Geo Arcade (165 Jogos MVS/AES) — Continue?</title>\r\n<link rel=\"icon\" type=\"image/png\" href=\"assets/continue-logo.png\">\r\n<link rel=\"shortcut icon\" type=\"image/png\" href=\"assets/continue-logo.png\">\r\n<link rel=\"apple-touch-icon\" href=\"assets/continue-logo.png\">\r\n<style>\r\n@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@600;700;800&display=swap');\r\n\r\n:root {\r\n  --bg: #111111;\r\n  --bg-soft: #161616;\r\n  --panel: #191919;\r\n  --panel-elevated: #222222;\r\n  --panel-hover: #282828;\r\n  --line: #2A2A2A;\r\n  --line-bright: #3D3D3D;\r\n  --ink: #F5F5F5;\r\n  --muted: #9E9E9E;\r\n  --dim: #666666;\r\n\r\n  --red: #E60012;\r\n  --red-hover: #FF1A2B;\r\n  --red-soft: rgba(230, 0, 18, 0.12);\r\n  --red-border: rgba(230, 0, 18, 0.38);\r\n  --amber: #F59E0B;\r\n  --amber-soft: rgba(245, 158, 11, 0.14);\r\n  --emerald: #10B981;\r\n  --emerald-soft: rgba(16, 185, 129, 0.14);\r\n  --cyan: #00E5FF;\r\n  --gold: #FFD700;\r\n\r\n  --mono: 'JetBrains Mono', monospace;\r\n  --sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;\r\n  --display: 'Space Grotesk', sans-serif;\r\n  --radius-lg: 14px;\r\n  --radius-md: 12px;\r\n  --radius-sm: 8px;\r\n}\r\n\r\n* {\r\n  box-sizing: border-box;\r\n}\r\n\r\nhtml {\r\n  scroll-behavior: smooth;\r\n  overflow-x: hidden;\r\n}\r\n\r\nbody {\r\n  margin: 0;\r\n  background-color: var(--bg);\r\n  color: var(--ink);\r\n  font-family: var(--sans);\r\n  min-height: 100vh;\r\n  overflow-x: hidden;\r\n  -webkit-font-smoothing: antialiased;\r\n}\r\n\r\nbutton, input, a {\r\n  font: inherit;\r\n  color: inherit;\r\n}\r\n\r\nbutton {\r\n  cursor: pointer;\r\n}\r\n\r\n.shell {\r\n  max-width: 1380px;\r\n  margin: 0 auto;\r\n  padding: 0 36px;\r\n}\r\n\r\n/* STICKY TOPBAR — HARDWARE CARBON */\r\n.topbar-wrap {\r\n  position: sticky;\r\n  top: 0;\r\n  z-index: 60;\r\n  background: rgba(17, 17, 17, 0.94);\r\n  backdrop-filter: blur(12px);\r\n  -webkit-backdrop-filter: blur(12px);\r\n  border-bottom: 1px solid var(--line);\r\n}\r\n\r\n.topbar {\r\n  max-width: 1380px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n  min-height: 64px;\r\n  height: auto;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 16px;\r\n  flex-wrap: nowrap;\r\n}\r\n\r\n.brand {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 12px;\r\n  text-decoration: none;\r\n  font-family: var(--display);\r\n  font-weight: 700;\r\n  font-size: 21px;\r\n  letter-spacing: -0.6px;\r\n  flex-shrink: 0;\r\n  color: #FFFFFF;\r\n  order: 1;\r\n}\r\n\r\n.brand-logo-img {\r\n  height: 44px;\r\n  width: auto;\r\n  max-width: 140px;\r\n  object-fit: contain;\r\n  display: block;\r\n  border-radius: 6px;\r\n  box-shadow: 0 0 14px rgba(230, 0, 18, 0.35);\r\n  border: 1px solid rgba(255, 255, 255, 0.12);\r\n  transition: transform 0.2s ease, box-shadow 0.2s ease;\r\n}\r\n\r\n.brand:hover .brand-logo-img {\r\n  transform: scale(1.05);\r\n  box-shadow: 0 0 22px rgba(230, 0, 18, 0.65);\r\n}\r\n\r\n.brand-mark {\r\n  width: 34px;\r\n  height: 34px;\r\n  background: var(--red);\r\n  color: #FFFFFF;\r\n  display: grid;\r\n  place-items: center;\r\n  border-radius: 8px;\r\n  font-size: 17px;\r\n  font-weight: 700;\r\n  transition: transform 0.18s ease, background 0.18s ease;\r\n}\r\n\r\n.brand:hover .brand-mark {\r\n  transform: translateY(-1px);\r\n  background: var(--red-hover);\r\n}\r\n\r\n.brand-q {\r\n  color: var(--red);\r\n}\r\n\r\n.brand-sub {\r\n  font: 700 10px var(--mono);\r\n  color: var(--gold);\r\n  text-transform: uppercase;\r\n  letter-spacing: 1.2px;\r\n  padding-left: 12px;\r\n  border-left: 1px solid var(--line-bright);\r\n}\r\n\r\n.nav {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  overflow-x: auto;\r\n  overflow-y: hidden;\r\n  white-space: nowrap;\r\n  -webkit-overflow-scrolling: touch;\r\n  scroll-behavior: smooth;\r\n  scrollbar-width: thin;\r\n  scrollbar-color: rgba(255, 184, 0, 0.45) rgba(255, 255, 255, 0.05);\r\n  flex: 1;\r\n  min-width: 0;\r\n  padding: 8px 12px 10px 4px;\r\n  order: 2;\r\n  font: 600 12px var(--sans);\r\n}\r\n\r\n.nav::-webkit-scrollbar {\r\n  height: 5px;\r\n  display: block;\r\n}\r\n\r\n.nav::-webkit-scrollbar-track {\r\n  background: rgba(255, 255, 255, 0.06);\r\n  border-radius: 999px;\r\n  margin: 0 4px;\r\n}\r\n\r\n.nav::-webkit-scrollbar-thumb {\r\n  background: linear-gradient(90deg, #ffb800, #ff4d5a);\r\n  border-radius: 999px;\r\n  box-shadow: 0 0 8px rgba(255, 184, 0, 0.5);\r\n}\r\n\r\n.nav::-webkit-scrollbar-thumb:hover {\r\n  background: linear-gradient(90deg, #00f0ff, #ffb800);\r\n}\r\n\r\n.nav-link {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 8px 14px;\r\n  border-radius: var(--radius-sm);\r\n  border: 1px solid transparent;\r\n  color: var(--muted);\r\n  text-decoration: none;\r\n  transition: all 0.16s ease;\r\n  white-space: nowrap;\r\n  background: transparent;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.nav-link:hover {\r\n  color: #FFFFFF;\r\n  background: var(--panel);\r\n  border-color: var(--line);\r\n}\r\n\r\n.nav-link.active {\r\n  color: #111111;\r\n  background: #FFFFFF;\r\n  border-color: #FFFFFF;\r\n  font-weight: 700;\r\n}\r\n\r\n.nav-badge {\r\n  font: 600 10px var(--mono);\r\n  padding: 2px 7px;\r\n  border-radius: 6px;\r\n  background: var(--panel-elevated);\r\n  color: var(--ink);\r\n  border: 1px solid var(--line-bright);\r\n}\r\n\r\n.nav-link.active .nav-badge {\r\n  background: #111111;\r\n  color: #FFFFFF;\r\n  border-color: #111111;\r\n}\r\n\r\n.nav-badge.red {\r\n  background: var(--red-soft);\r\n  color: #FF4D5A;\r\n  border-color: var(--red-border);\r\n}\r\n\r\n.nav-badge.gold {\r\n  background: rgba(255, 215, 0, 0.15);\r\n  color: #FFD700;\r\n  border-color: rgba(255, 215, 0, 0.4);\r\n}\r\n\r\n.top-right-actions {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  flex-shrink: 0;\r\n  order: 3;\r\n  padding-left: 14px;\r\n  border-left: 1px solid rgba(255, 255, 255, 0.08);\r\n  position: relative;\r\n  z-index: 5;\r\n}\r\n\r\n.btn-top-mapper {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 7px;\r\n  background: var(--panel-elevated);\r\n  border: 1px solid var(--line-bright);\r\n  color: #FFFFFF;\r\n  font: 700 12px var(--sans);\r\n  padding: 8px 14px;\r\n  border-radius: var(--radius-sm);\r\n  cursor: pointer;\r\n  transition: all 0.16s ease;\r\n}\r\n\r\n.btn-top-mapper:hover {\r\n  border-color: #FFFFFF;\r\n  background: var(--panel-hover);\r\n}\r\n\r\n.pad-dot {\r\n  width: 8px;\r\n  height: 8px;\r\n  border-radius: 50%;\r\n  background: var(--emerald);\r\n  display: inline-block;\r\n  box-shadow: 0 0 8px var(--emerald);\r\n}\r\n\r\n/* HERO */\r\n.hero {\r\n  padding: 38px 0 26px;\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: flex-end;\r\n  gap: 28px;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.eyebrow {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  font: 700 11px var(--mono);\r\n  text-transform: uppercase;\r\n  letter-spacing: 1.2px;\r\n  color: #FFFFFF;\r\n  background: var(--panel);\r\n  border: 1px solid var(--line-bright);\r\n  border-left: 3px solid var(--gold);\r\n  padding: 6px 12px;\r\n  border-radius: 6px;\r\n}\r\n\r\n.hero h1 {\r\n  font-family: var(--display);\r\n  font-size: clamp(36px, 5vw, 62px);\r\n  letter-spacing: -2.3px;\r\n  line-height: 0.97;\r\n  margin: 14px 0 12px;\r\n  color: #FFFFFF;\r\n}\r\n\r\n.hero h1 span {\r\n  color: var(--gold);\r\n  text-shadow: 0 0 24px rgba(255, 215, 0, 0.35);\r\n}\r\n\r\n.intro {\r\n  max-width: 680px;\r\n  color: var(--muted);\r\n  line-height: 1.62;\r\n  font-size: 15.5px;\r\n  margin: 0;\r\n}\r\n\r\n.intro b {\r\n  color: #FFFFFF;\r\n}\r\n\r\n.hero-actions {\r\n  display: flex;\r\n  gap: 10px;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.btn-mapper-hero {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 8px;\r\n  min-height: 48px;\r\n  padding: 13px 20px;\r\n  border-radius: var(--radius-sm);\r\n  border: 1px solid var(--red);\r\n  background: var(--red);\r\n  color: #FFFFFF;\r\n  font: 700 13px var(--sans);\r\n  transition: background 0.16s ease, transform 0.16s ease;\r\n}\r\n\r\n.btn-mapper-hero:hover {\r\n  background: var(--red-hover);\r\n  transform: translateY(-2px);\r\n}\r\n\r\n.btn-mapper-hero.gold {\r\n  border-color: #D4AF37;\r\n  background: linear-gradient(135deg, #F59E0B, #B45309);\r\n  color: #FFFFFF;\r\n  box-shadow: 0 4px 14px rgba(245, 158, 11, 0.35);\r\n}\r\n\r\n.btn-mapper-hero.gold:hover {\r\n  background: linear-gradient(135deg, #FBBF24, #D97706);\r\n}\r\n\r\n/* SECTION JUMP BAR */\r\n.section-nav {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 12px;\r\n  flex-wrap: wrap;\r\n  padding: 12px 16px;\r\n  background: var(--panel);\r\n  border: 1px solid var(--line);\r\n  border-radius: var(--radius-md);\r\n  margin-bottom: 26px;\r\n}\r\n\r\n.jump-links {\r\n  display: flex;\r\n  gap: 8px;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.jump-pill {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 9px 13px;\r\n  border-radius: var(--radius-sm);\r\n  background: var(--panel-elevated);\r\n  border: 1px solid var(--line-bright);\r\n  text-decoration: none;\r\n  font: 600 12.5px var(--sans);\r\n  color: var(--ink);\r\n  transition: all 0.16s ease;\r\n}\r\n\r\n.jump-pill span {\r\n  font: 700 10px var(--mono);\r\n  color: #111111;\r\n  background: var(--gold);\r\n  padding: 2px 6px;\r\n  border-radius: 4px;\r\n}\r\n\r\n.jump-pill:hover {\r\n  border-color: #FFFFFF;\r\n  background: var(--panel-hover);\r\n  color: #FFFFFF;\r\n}\r\n\r\n/* THEATER MODE NEO GEO PLAYER DOCK */\r\n.player-dock {\r\n  display: none;\r\n  margin: 0 0 36px;\r\n  border: 2px solid var(--line-bright);\r\n  border-top: 4px solid var(--gold);\r\n  border-radius: var(--radius-lg);\r\n  background: #0A0A0A;\r\n  overflow: hidden;\r\n  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.85);\r\n}\r\n\r\n.player-dock.open {\r\n  display: block;\r\n}\r\n\r\n.player-head {\r\n  padding: 14px 18px;\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  gap: 14px;\r\n  flex-wrap: wrap;\r\n  background: var(--panel);\r\n  border-bottom: 1px solid var(--line);\r\n}\r\n\r\n.player-now {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 14px;\r\n  min-width: 0;\r\n}\r\n\r\n.player-thumb {\r\n  width: 52px;\r\n  height: 52px;\r\n  border-radius: 6px;\r\n  object-fit: cover;\r\n  border: 1px solid var(--line-bright);\r\n  background: #0C0C0C;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.player-kicker {\r\n  font: 700 10px var(--mono);\r\n  color: var(--gold);\r\n  text-transform: uppercase;\r\n  letter-spacing: 1.2px;\r\n}\r\n\r\n.player-title {\r\n  font-family: var(--display);\r\n  font-size: 18px;\r\n  font-weight: 700;\r\n  letter-spacing: -0.4px;\r\n  color: #FFFFFF;\r\n}\r\n\r\n.player-controls-bar {\r\n  display: flex;\r\n  gap: 8px;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.dock-btn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  min-height: 40px;\r\n  padding: 8px 14px;\r\n  border-radius: var(--radius-sm);\r\n  border: 1px solid var(--line-bright);\r\n  background: var(--panel-elevated);\r\n  color: #FFFFFF;\r\n  font: 700 12px var(--sans);\r\n  transition: all 0.16s ease;\r\n}\r\n\r\n.dock-btn:hover {\r\n  border-color: #FFFFFF;\r\n  background: var(--panel-hover);\r\n}\r\n\r\n.dock-btn.active {\r\n  border-color: var(--amber);\r\n  color: var(--amber);\r\n  background: var(--amber-soft);\r\n}\r\n\r\n.dock-btn.danger {\r\n  background: rgba(230, 0, 18, 0.16);\r\n  border-color: var(--red-border);\r\n}\r\n\r\n.dock-btn.danger:hover {\r\n  border-color: var(--red);\r\n  background: var(--red);\r\n  color: #FFFFFF;\r\n}\r\n\r\n.control-note {\r\n  padding: 12px 18px;\r\n  background: var(--bg-soft);\r\n  color: var(--muted);\r\n  border-bottom: 1px solid var(--line);\r\n  font: 600 12px var(--sans);\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: 10px;\r\n}\r\n\r\n.control-note b {\r\n  color: #FFFFFF;\r\n}\r\n\r\n#game-frame {\r\n  height: min(74vh, 720px);\r\n  min-height: 380px;\r\n  width: 100%;\r\n  border: 0;\r\n  display: block;\r\n  background: #080808;\r\n}\r\n\r\n/* ARCHITECTURAL SECTIONS */\r\n.lib-section {\r\n  padding: 32px 0 38px;\r\n  border-top: 1px solid var(--line);\r\n}\r\n\r\n.section-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: flex-end;\r\n  gap: 16px;\r\n  margin-bottom: 22px;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.section-index {\r\n  font: 700 11px var(--mono);\r\n  text-transform: uppercase;\r\n  letter-spacing: 1.4px;\r\n  color: var(--gold);\r\n  margin-bottom: 6px;\r\n}\r\n\r\n.section-header h2 {\r\n  font-family: var(--display);\r\n  font-size: clamp(22px, 2.8vw, 30px);\r\n  letter-spacing: -0.8px;\r\n  margin: 0;\r\n  color: #FFFFFF;\r\n}\r\n\r\n.section-sub {\r\n  font-size: 14px;\r\n  color: var(--muted);\r\n  margin: 5px 0 0;\r\n}\r\n\r\n/* ARCADE SHOWCASE (SEÇÃO A) */\r\n.arcade-showcase {\r\n  display: grid;\r\n  grid-template-columns: repeat(2, 1fr);\r\n  gap: 18px;\r\n}\r\n\r\n.arcade-card {\r\n  display: grid;\r\n  grid-template-columns: 240px 1fr;\r\n  background: var(--panel);\r\n  border: 1px solid var(--line-bright);\r\n  border-radius: var(--radius-lg);\r\n  overflow: hidden;\r\n  transition: transform 0.16s ease, border-color 0.16s ease;\r\n}\r\n\r\n.arcade-card:hover {\r\n  transform: translateY(-2px);\r\n  border-color: var(--gold);\r\n}\r\n\r\n.arcade-art {\r\n  position: relative;\r\n  background: #0C0C0C;\r\n  display: grid;\r\n  place-items: center;\r\n  border-right: 1px solid var(--line);\r\n  overflow: hidden;\r\n  min-height: 230px;\r\n  cursor: pointer;\r\n}\r\n\r\n.arcade-art-img {\r\n  position: relative;\r\n  z-index: 1;\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n  transition: transform 0.2s ease;\r\n}\r\n\r\n.arcade-card:hover .arcade-art-img {\r\n  transform: scale(1.03);\r\n}\r\n\r\n.arcade-body {\r\n  padding: 20px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: space-between;\r\n  gap: 14px;\r\n}\r\n\r\n.arcade-badges {\r\n  display: flex;\r\n  gap: 6px;\r\n  flex-wrap: wrap;\r\n  margin-bottom: 10px;\r\n}\r\n\r\n.pill {\r\n  font: 700 9.5px var(--mono);\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.5px;\r\n  padding: 4px 8px;\r\n  border-radius: 5px;\r\n  background: rgba(17, 17, 17, 0.92);\r\n  color: #FFFFFF;\r\n  border: 1px solid var(--line-bright);\r\n}\r\n\r\n.pill.neogeo {\r\n  background: var(--red);\r\n  color: #FFFFFF;\r\n  border-color: var(--red);\r\n}\r\n\r\n.pill.gold {\r\n  background: rgba(255, 215, 0, 0.2);\r\n  color: #FFD700;\r\n  border-color: rgba(255, 215, 0, 0.5);\r\n}\r\n\r\n.arcade-body h3 {\r\n  font-family: var(--display);\r\n  font-size: 22px;\r\n  letter-spacing: -0.5px;\r\n  margin: 0 0 8px;\r\n  line-height: 1.22;\r\n  color: #FFFFFF;\r\n}\r\n\r\n.arcade-body p {\r\n  font-size: 13.5px;\r\n  color: var(--muted);\r\n  line-height: 1.55;\r\n  margin: 0;\r\n}\r\n\r\n.arcade-actions {\r\n  display: flex;\r\n  gap: 10px;\r\n  align-items: center;\r\n  padding-top: 12px;\r\n  border-top: 1px solid var(--line);\r\n}\r\n\r\n.btn-launch-neogeo {\r\n  flex: 1;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 8px;\r\n  min-height: 44px;\r\n  padding: 11px 16px;\r\n  border-radius: var(--radius-sm);\r\n  border: 1px solid var(--red);\r\n  background: var(--red);\r\n  color: #FFFFFF;\r\n  font: 700 12.5px var(--sans);\r\n  transition: background 0.16s ease, transform 0.16s ease;\r\n}\r\n\r\n.btn-launch-neogeo:hover {\r\n  background: var(--red-hover);\r\n  transform: translateY(-1px);\r\n}\r\n\r\n/* BANNER DE BUSCA NO TOPO */\r\n.top-search-banner {\r\n  background: var(--panel);\r\n  border: 1px solid var(--line-bright);\r\n  border-radius: var(--radius-md);\r\n  padding: 16px 20px;\r\n  margin: 18px 0 28px;\r\n  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.45);\r\n}\r\n\r\n.top-search-box {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 12px;\r\n  background: #0A0A0A;\r\n  border: 1.5px solid var(--line-bright);\r\n  border-radius: var(--radius-sm);\r\n  padding: 0 16px;\r\n  height: 52px;\r\n  transition: border-color 0.2s, box-shadow 0.2s;\r\n}\r\n\r\n.top-search-box:focus-within {\r\n  border-color: var(--gold);\r\n  box-shadow: 0 0 0 3px rgba(255, 215, 0, 0.2);\r\n}\r\n\r\n.top-search-box svg {\r\n  color: var(--gold);\r\n  flex-shrink: 0;\r\n}\r\n\r\n.top-search-box input {\r\n  flex: 1;\r\n  background: transparent;\r\n  border: 0;\r\n  outline: 0;\r\n  color: #FFFFFF;\r\n  font-size: 15px;\r\n  font-weight: 600;\r\n}\r\n\r\n.top-search-box input::placeholder {\r\n  color: #888888;\r\n  font-weight: 400;\r\n}\r\n\r\n.top-clear-btn {\r\n  background: var(--panel-elevated);\r\n  border: 1px solid var(--line-bright);\r\n  border-radius: 6px;\r\n  color: #FFFFFF;\r\n  font: 700 11px var(--sans);\r\n  padding: 6px 12px;\r\n  cursor: pointer;\r\n  display: none;\r\n}\r\n\r\n.top-clear-btn.visible {\r\n  display: inline-block;\r\n}\r\n\r\n.top-clear-btn:hover {\r\n  background: var(--red);\r\n  border-color: var(--red);\r\n}\r\n\r\n.top-search-hints {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  flex-wrap: wrap;\r\n  margin-top: 12px;\r\n  font-size: 12.5px;\r\n  color: var(--muted);\r\n}\r\n\r\n.search-tag {\r\n  background: var(--bg-soft);\r\n  border: 1px solid var(--line-bright);\r\n  color: #EEEEEE;\r\n  padding: 5px 12px;\r\n  border-radius: 20px;\r\n  font: 600 12px var(--sans);\r\n  cursor: pointer;\r\n  transition: all 0.15s;\r\n}\r\n\r\n.search-tag:hover {\r\n  background: var(--gold);\r\n  color: #111111;\r\n  border-color: var(--gold);\r\n  font-weight: 700;\r\n  transform: translateY(-1px);\r\n}\r\n\r\n/* CONTROL DECK (SEÇÃO B) */\r\n.control-deck {\r\n  background: var(--panel);\r\n  border: 1px solid var(--line-bright);\r\n  border-radius: var(--radius-lg);\r\n  padding: 16px;\r\n  margin-bottom: 20px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 14px;\r\n}\r\n\r\n.deck-top {\r\n  display: flex;\r\n  gap: 12px;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.search-wrap {\r\n  flex: 1;\r\n  min-width: 240px;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n  background: #111111;\r\n  border: 1px solid var(--line-bright);\r\n  border-radius: var(--radius-sm);\r\n  padding: 0 14px;\r\n  height: 46px;\r\n  transition: border-color 0.18s;\r\n}\r\n\r\n.search-wrap:focus-within {\r\n  border-color: var(--gold);\r\n}\r\n\r\n.search-wrap input {\r\n  flex: 1;\r\n  background: transparent;\r\n  border: 0;\r\n  outline: 0;\r\n  color: #FFFFFF;\r\n  font-size: 14px;\r\n}\r\n\r\n.genre-tabs {\r\n  display: flex;\r\n  gap: 7px;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.genre-tab {\r\n  border: 1px solid var(--line);\r\n  background: var(--panel-elevated);\r\n  color: var(--muted);\r\n  min-height: 38px;\r\n  padding: 8px 13px;\r\n  border-radius: var(--radius-sm);\r\n  font: 600 12px var(--sans);\r\n  transition: all 0.16s ease;\r\n}\r\n\r\n.genre-tab:hover {\r\n  color: #FFFFFF;\r\n  border-color: var(--line-bright);\r\n  background: var(--panel-hover);\r\n}\r\n\r\n.genre-tab.active {\r\n  background: #FFFFFF;\r\n  border-color: #FFFFFF;\r\n  color: #111111;\r\n  font-weight: 700;\r\n}\r\n\r\n.letter-row {\r\n  display: flex;\r\n  gap: 6px;\r\n  flex-wrap: wrap;\r\n  padding-top: 10px;\r\n  border-top: 1px solid var(--line);\r\n}\r\n\r\n.letter {\r\n  border: 1px solid var(--line);\r\n  background: #111111;\r\n  color: var(--muted);\r\n  min-height: 36px;\r\n  padding: 6px 10px;\r\n  border-radius: 6px;\r\n  font: 700 11.5px var(--mono);\r\n  transition: all 0.15s ease;\r\n}\r\n\r\n.letter:hover {\r\n  color: #FFFFFF;\r\n  border-color: var(--line-bright);\r\n}\r\n\r\n.letter.active {\r\n  background: var(--red);\r\n  border-color: var(--red);\r\n  color: #FFFFFF;\r\n  font-weight: 700;\r\n}\r\n\r\n/* CATALOG CARDS GRID */\r\n.grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));\r\n  gap: 16px;\r\n}\r\n\r\n.card {\r\n  border: 1px solid var(--line);\r\n  background: var(--panel);\r\n  border-radius: var(--radius-md);\r\n  overflow: hidden;\r\n  display: flex;\r\n  flex-direction: column;\r\n  transition: transform 0.16s ease, border-color 0.16s ease;\r\n  position: relative;\r\n}\r\n\r\n.card:hover {\r\n  transform: translateY(-2px);\r\n  border-color: var(--line-bright);\r\n}\r\n\r\n.art {\r\n  aspect-ratio: 16 / 10;\r\n  position: relative;\r\n  overflow: hidden;\r\n  background: #0C0C0C;\r\n  display: grid;\r\n  place-items: center;\r\n  border-bottom: 1px solid var(--line);\r\n  cursor: pointer;\r\n}\r\n\r\n.art-img {\r\n  position: relative;\r\n  z-index: 1;\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n  transition: transform 0.2s ease;\r\n}\r\n\r\n.card:hover .art-img {\r\n  transform: scale(1.03);\r\n}\r\n\r\n.art-fallback {\r\n  position: relative;\r\n  z-index: 1;\r\n  padding: 14px;\r\n  text-align: center;\r\n  font-weight: 700;\r\n  font-size: 16px;\r\n  color: #FFFFFF;\r\n}\r\n\r\n.card-badges {\r\n  position: absolute;\r\n  top: 9px;\r\n  left: 9px;\r\n  z-index: 2;\r\n  display: flex;\r\n  gap: 5px;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.fav-btn {\r\n  position: absolute;\r\n  top: 9px;\r\n  right: 9px;\r\n  z-index: 3;\r\n  width: 34px;\r\n  height: 34px;\r\n  border-radius: 8px;\r\n  border: 1px solid var(--line-bright);\r\n  background: rgba(17, 17, 17, 0.9);\r\n  color: var(--muted);\r\n  display: grid;\r\n  place-items: center;\r\n  font-size: 15px;\r\n}\r\n\r\n.fav-btn:hover {\r\n  color: #FFFFFF;\r\n  border-color: #FFFFFF;\r\n}\r\n\r\n.fav-btn.active {\r\n  color: var(--amber);\r\n  border-color: var(--amber);\r\n  background: rgba(245, 158, 11, 0.18);\r\n}\r\n\r\n.info {\r\n  padding: 14px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: space-between;\r\n  flex: 1;\r\n  gap: 10px;\r\n}\r\n\r\n.title {\r\n  font-size: 15px;\r\n  font-weight: 700;\r\n  color: #FFFFFF;\r\n  line-height: 1.32;\r\n}\r\n\r\n.raw-sub {\r\n  font: 600 11px var(--mono);\r\n  color: var(--gold);\r\n  margin-top: 4px;\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n}\r\n\r\n.meta {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  font: 600 10.5px var(--mono);\r\n  color: var(--muted);\r\n  padding-top: 10px;\r\n  border-top: 1px solid var(--line);\r\n}\r\n\r\n.play {\r\n  border: 1px solid var(--red);\r\n  background: var(--red);\r\n  color: #FFFFFF;\r\n  min-height: 38px;\r\n  padding: 8px 14px;\r\n  border-radius: 7px;\r\n  font: 700 11.5px var(--sans);\r\n  transition: all 0.15s ease;\r\n}\r\n\r\n.play:hover {\r\n  background: var(--red-hover);\r\n  border-color: var(--red-hover);\r\n}\r\n\r\n/* SEÇÃO C: ARCADE GUIDE */\r\n.guide-grid {\r\n  display: grid;\r\n  grid-template-columns: 1.1fr 0.9fr;\r\n  gap: 18px;\r\n}\r\n\r\n.guide-card {\r\n  background: var(--panel);\r\n  border: 1px solid var(--line-bright);\r\n  border-radius: var(--radius-lg);\r\n  padding: 20px;\r\n}\r\n\r\n.guide-card h3 {\r\n  font-family: var(--display);\r\n  font-size: 18px;\r\n  margin: 0 0 12px;\r\n  letter-spacing: -0.4px;\r\n  color: #FFFFFF;\r\n}\r\n\r\n.keymap-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(2, 1fr);\r\n  gap: 8px;\r\n  font: 600 11.5px var(--sans);\r\n}\r\n\r\n.key-row {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  padding: 8px 10px;\r\n  background: var(--panel-elevated);\r\n  border: 1px solid var(--line);\r\n  border-radius: 6px;\r\n}\r\n\r\n.key-row b {\r\n  color: #FFFFFF;\r\n  background: var(--red);\r\n  padding: 2px 7px;\r\n  border-radius: 4px;\r\n  font: 700 10.5px var(--mono);\r\n}\r\n\r\n.key-row b.gold {\r\n  background: var(--amber);\r\n  color: #111111;\r\n}\r\n\r\n.key-row b.green {\r\n  background: var(--emerald);\r\n}\r\n\r\n.empty {\r\n  padding: 34px 20px;\r\n  border: 1px dashed var(--line-bright);\r\n  color: var(--muted);\r\n  border-radius: var(--radius-md);\r\n  grid-column: 1 / -1;\r\n  text-align: center;\r\n  font: 600 13px var(--sans);\r\n}\r\n\r\n.footer {\r\n  padding: 28px 0 42px;\r\n  color: var(--muted);\r\n  font: 500 11px var(--mono);\r\n  border-top: 1px solid var(--line);\r\n  margin-top: 44px;\r\n  display: flex;\r\n  justify-content: space-between;\r\n  flex-wrap: wrap;\r\n  gap: 14px;\r\n}\r\n\r\n.footer b {\r\n  color: #FFFFFF;\r\n  font-weight: 600;\r\n}\r\n\r\n@media (max-width: 960px) {\r\n  .arcade-showcase,\r\n  .guide-grid {\r\n    grid-template-columns: 1fr;\r\n  }\r\n}\r\n\r\n@media (max-width: 820px) {\r\n  .shell {\r\n    padding: 0 16px;\r\n  }\r\n  .topbar {\r\n    flex-wrap: wrap;\r\n    padding: 10px 16px 6px;\r\n    height: auto;\r\n    min-height: unset;\r\n    gap: 0;\r\n  }\r\n  .brand {\r\n    order: 1;\r\n  }\r\n  .brand-sub {\r\n    display: none;\r\n  }\r\n  .top-right-actions {\r\n    order: 2;\r\n    margin-left: auto;\r\n    gap: 8px;\r\n    padding-left: 0;\r\n    border-left: none;\r\n  }\r\n  .nav {\r\n    order: 3;\r\n    width: 100%;\r\n    flex: 0 0 100%;\r\n    margin-top: 8px;\r\n    padding: 8px 0 10px;\r\n    border-top: 1px solid var(--line);\r\n    overflow-x: auto;\r\n    overflow-y: hidden;\r\n    white-space: nowrap;\r\n    -webkit-overflow-scrolling: touch;\r\n  }\r\n  .hero {\r\n    padding: 24px 0 20px;\r\n    gap: 20px;\r\n  }\r\n  .arcade-card {\r\n    grid-template-columns: 1fr;\r\n  }\r\n  .arcade-art {\r\n    border-right: 0;\r\n    border-bottom: 1px solid var(--line);\r\n    min-height: 200px;\r\n  }\r\n  .keymap-grid {\r\n    grid-template-columns: 1fr;\r\n  }\r\n  #game-frame {\r\n    min-height: 220px;\r\n  }\r\n}\r\n\r\n@media (max-width: 600px) {\r\n  .grid {\r\n    grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));\r\n    gap: 12px;\r\n  }\r\n  .card-badges {\r\n    top: 6px;\r\n    left: 6px;\r\n  }\r\n  .fav-btn {\r\n    top: 6px;\r\n    right: 6px;\r\n    width: 30px;\r\n    height: 30px;\r\n    font-size: 14px;\r\n  }\r\n  .info {\r\n    padding: 12px;\r\n    gap: 8px;\r\n  }\r\n  .title {\r\n    font-size: 14px;\r\n  }\r\n  .player-dock {\r\n    margin-bottom: 24px;\r\n  }\r\n  .player-head {\r\n    padding: 10px 12px;\r\n    gap: 10px;\r\n  }\r\n  .player-now {\r\n    width: 100%;\r\n    gap: 10px;\r\n  }\r\n  .player-thumb {\r\n    width: 44px;\r\n    height: 44px;\r\n    flex-shrink: 0;\r\n  }\r\n  .player-title {\r\n    font-size: 15px;\r\n    line-height: 1.25;\r\n    word-break: break-word;\r\n  }\r\n  .player-controls-bar {\r\n    width: 100%;\r\n    flex-wrap: wrap;\r\n    gap: 6px;\r\n  }\r\n  .dock-btn {\r\n    padding: 7px 10px;\r\n    font-size: 11.5px;\r\n    flex: 1 1 auto;\r\n    min-width: calc(50% - 6px);\r\n    text-align: center;\r\n    justify-content: center;\r\n    min-height: 36px;\r\n  }\r\n  .cheat-sheet {\r\n    font-size: 11px;\r\n    padding: 10px 12px;\r\n    flex-direction: column;\r\n    gap: 6px;\r\n  }\r\n  .btn-top-mapper {\r\n    padding: 6px 10px;\r\n    font-size: 11px;\r\n  }\r\n  .brand-logo-img {\r\n    height: 34px;\r\n  }\r\n}\r\n</style>\r\n<script src=\"assets/gamepad-mapper.js\" defer></script>\r\n<script src=\"assets/retro-bg.js\" defer></script>\r\n</head>\r\n<body>\r\n\r\n<div class=\"topbar-wrap\">\r\n  <header class=\"topbar\">\r\n    <a class=\"brand\" href=\"index.html\" title=\"Continue? — Videogame Grátis\">\r\n      <img src=\"assets/continue-logo.png\" alt=\"Continue?\" class=\"brand-logo-img\">\r\n      <span class=\"brand-sub\">NEO GEO (MVS/AES)</span>\r\n    </a>\r\n    <nav class=\"nav\" aria-label=\"Navegação Principal\">\r\n      <a class=\"nav-link\" href=\"index.html\">🏠 Início</a>\r\n      <a class=\"nav-link\" href=\"snes.html\">🎮 Super Nintendo <span class=\"nav-badge\">550</span></a>\r\n      <a class=\"nav-link\" href=\"ps1.html\">💿 PlayStation 1 <span class=\"nav-badge\">16</span></a>\r\n      <a class=\"nav-link active\" href=\"neogeo.html\">🕹️ Neo Geo <span class=\"nav-badge gold\" id=\"nav-neogeo-count\">165</span></a>\r\n      <a class=\"nav-link\" href=\"n64.html\">🌟 Nintendo 64 <span class=\"nav-badge\">7</span></a>\r\n      <a class=\"nav-link\" href=\"gameboy.html\">📱 Game Boy <span class=\"nav-badge\">6</span></a>\r\n      <a class=\"nav-link\" href=\"sega.html\">⚡ Mega Drive <span class=\"nav-badge\">6</span></a>\r\n      <a class=\"nav-link\" href=\"psp.html\">🚀 PSP <span class=\"nav-badge\">2</span></a>\r\n      <a class=\"nav-link\" href=\"#catalogo\" id=\"nav-fav-trigger\">★ Favoritos <span class=\"nav-badge red\" id=\"fav-nav-count\">0</span></a>\r\n    </nav>\r\n    <div class=\"top-right-actions\">\r\n      <button type=\"button\" class=\"btn-top-mapper\" data-open-mapper title=\"Configurar Controle, Teclado ou Botões do Celular\">\r\n        <span class=\"pad-dot\"></span> 🕹️ Configurar Controle\r\n      </button>\r\n    </div>\r\n  </header>\r\n</div>\r\n\r\n<div class=\"shell\">\r\n  <main>\r\n    <!-- HERO -->\r\n    <section class=\"hero\">\r\n      <div>\r\n        <div class=\"eyebrow\">// 165 clássicos de fliperama (100 MEGA SHOCK) • celular, pc e controle</div>\r\n        <h1>Neo Geo Arcade:<br><span>coloque a ficha e lute!</span></h1>\r\n        <p class=\"intro\">\r\n          São <b>165 lendários jogos de fliperama da SNK</b>! Toda a saga <b>The King of Fighters</b> (do 94 ao 2003), <b>Metal Slug</b> (1, 2, X, 3, 4, 5), <b>Samurai Shodown</b>, <b>Fatal Fury</b>, <b>Real Bout</b>, <b>Windjammers</b>, <b>Neo Turf Masters</b> e <b>Sengoku 3</b>. <b>No celular, os botões virtuais A, B, C, D e Ficha já aparecem na tela!</b>\r\n        </p>\r\n      </div>\r\n      <div class=\"hero-actions\">\r\n        <button class=\"btn-mapper-hero gold\" id=\"btn-random-neogeo\" type=\"button\">🎲 Jogo Surpresa!</button>\r\n        <button class=\"btn-mapper-hero\" type=\"button\" data-open-mapper style=\"background:var(--panel-elevated);border-color:var(--line-bright)\">🕹️ Configurar Controle</button>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- BARRA DE BUSCA PRINCIPAL (NO TOPO) -->\r\n    <div class=\"top-search-banner\">\r\n      <label class=\"top-search-box\">\r\n        <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\">\r\n          <circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/>\r\n        </svg>\r\n        <input id=\"search-top\" type=\"search\" placeholder=\"🔍 Digite o nome do jogo de Neo Geo (ex: KOF 2002, Metal Slug, Samurai Shodown, Fatal Fury, Windjammers)...\" aria-label=\"Buscar jogo\">\r\n        <button class=\"top-clear-btn\" id=\"clear-search-top\" type=\"button\">LIMPAR ✕</button>\r\n      </label>\r\n      <div class=\"top-search-hints\">\r\n        <span>⚡ <b>Busca Rápida:</b></span>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Todos\">Todos</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"The King of Fighters\">The King of Fighters</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Metal Slug\">Metal Slug</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Samurai Shodown\">Samurai Shodown</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Fatal Fury\">Fatal Fury</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Luta\">Luta</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Tiro\">Ação / Tiro</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Esportes\">Esportes</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Nave\">Nave</button>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- QUICK SECTION JUMP BAR -->\r\n    <nav class=\"section-nav\" aria-label=\"Atalhos da Biblioteca Neo Geo\">\r\n      <div class=\"jump-links\">\r\n        <a class=\"jump-pill\" href=\"#destaques\"><span>A</span> Destaques do Fliperama (12)</a>\r\n        <a class=\"jump-pill\" href=\"#catalogo\"><span>B</span> Todos os 165 Jogos & Filtros</a>\r\n        <a class=\"jump-pill\" href=\"#guia-neogeo\"><span>C</span> Comandos & Fichas</a>\r\n      </div>\r\n      <span style=\"font:600 12px var(--sans);color:var(--muted)\">📱 Toque em qualquer capinha para colocar a ficha e jogar!</span>\r\n    </nav>\r\n\r\n    <!-- THEATER MODE NEO GEO PLAYER DOCK -->\r\n    <section class=\"player-dock\" id=\"player\" aria-label=\"Emulador Neo Geo\">\r\n      <div class=\"player-head\">\r\n        <div class=\"player-now\">\r\n          <img class=\"player-thumb\" id=\"playing-thumb\" src=\"assets/covers/neogeo/kof2002.svg\" alt=\"Capa do jogo\">\r\n          <div>\r\n            <div class=\"player-kicker\" id=\"playing-meta\">// JOGANDO AGORA • NEO GEO (MVS/AES) • FLIPERAMA</div>\r\n            <div class=\"player-title\" id=\"playing\">Carregando jogo…</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"player-controls-bar\">\r\n          <button class=\"dock-btn\" type=\"button\" data-open-mapper>🕹️ Controle</button>\r\n          <button class=\"dock-btn\" id=\"dock-fav\" type=\"button\">★ Favoritar</button>\r\n          <button class=\"dock-btn\" id=\"dock-fullscreen\" type=\"button\">⛶ Tela Cheia</button>\r\n          <button class=\"dock-btn danger\" id=\"close\" type=\"button\">✕ Fechar Jogo</button>\r\n        </div>\r\n      </div>\r\n      <div class=\"control-note\">\r\n        <span>🪙 <b>FICHA:</b> Aperte <b>V</b>, <b>C</b> ou <b>5</b> · ▶ <b>START:</b> Aperte <b>Enter</b> ou <b>1</b> · 📱 <b>CELULAR:</b> Botões virtuais na tela! · ⌨️ <b>TECLADO:</b> Z, X, A, S</span>\r\n        <span>Quer mudar os botões? Toque em <b>🕹️ Controle</b> acima!</span>\r\n      </div>\r\n      <iframe id=\"game-frame\" title=\"Emulador Neo Geo Arcade\" allow=\"autoplay; fullscreen; gamepad\" allowfullscreen></iframe>\r\n    </section>\r\n\r\n    <!-- SEÇÃO A: DESTAQUES FLIPERAMA NEO GEO -->\r\n    <section class=\"lib-section\" id=\"destaques\">\r\n      <div class=\"section-header\">\r\n        <div>\r\n          <div class=\"section-index\">// seção A · os maiores clássicos dos fliperamas</div>\r\n          <h2>Destaques Neo Geo Arcade (100 Mega Shock)</h2>\r\n          <p class=\"section-sub\">KOF 2002, KOF 98, Metal Slug X, Samurai Shodown II, Fatal Fury Special, Windjammers e muito mais — toque na capa para jogar!</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"arcade-showcase\" id=\"arcade-showcase\"></div>\r\n    </section>\r\n\r\n    <!-- SEÇÃO B: CATÁLOGO COMPLETO & FILTROS -->\r\n    <section class=\"lib-section\" id=\"catalogo\">\r\n      <div class=\"section-header\">\r\n        <div>\r\n          <div class=\"section-index\">// seção B · todos os 165 clássicos</div>\r\n          <h2>Catálogo Completo & Filtros por Gênero</h2>\r\n          <p class=\"section-sub\">Filtre por tipo de jogo (Luta, Ação / Tiro, Esportes, Nave, Puzzle) ou procure pelo nome.</p>\r\n        </div>\r\n        <span id=\"count\" style=\"font:700 12.5px var(--mono);color:#FFFFFF\">Carregando jogos…</span>\r\n      </div>\r\n\r\n      <div class=\"control-deck\">\r\n        <div class=\"deck-top\">\r\n          <label class=\"search-wrap\">\r\n            <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\r\n              <circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/>\r\n            </svg>\r\n            <input id=\"search\" type=\"search\" placeholder=\"Buscar jogo de Neo Geo pelo nome…\" aria-label=\"Buscar jogo pelo nome\">\r\n          </label>\r\n          <div class=\"genre-tabs\" id=\"genre-tabs\"></div>\r\n        </div>\r\n        <div class=\"letter-row\" id=\"letters\" aria-label=\"Filtrar por letra\"></div>\r\n      </div>\r\n\r\n      <div class=\"grid\" id=\"grid\">\r\n        <div class=\"empty\">Carregando os clássicos de Neo Geo…</div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- SEÇÃO C: GUIA ARCADE & AJUDA -->\r\n    <section class=\"lib-section\" id=\"guia-neogeo\">\r\n      <div class=\"section-header\">\r\n        <div>\r\n          <div class=\"section-index\">// seção C · comandos & ajuda rápida</div>\r\n          <h2>Botões do Fliperama, Fichas & Controles</h2>\r\n          <p class=\"section-sub\">Veja os comandos padrão ou clique no botão abaixo para mapear seu Controle USB/Bluetooth passo a passo!</p>\r\n        </div>\r\n        <button class=\"btn-mapper-hero\" type=\"button\" data-open-mapper style=\"min-height:42px;padding:10px 16px;font-size:12px\">🎯 Configurar Meu Controle</button>\r\n      </div>\r\n\r\n      <div class=\"guide-grid\">\r\n        <div class=\"guide-card\">\r\n          <h3>🕹️ Botões Padrão no Teclado e Controle</h3>\r\n          <div class=\"keymap-grid\">\r\n            <div class=\"key-row\"><span>Botão A (Soco Fraco / Pulo)</span><b>Tecla Z / Botão Sul</b></div>\r\n            <div class=\"key-row\"><span>Botão B (Chute Fraco / Golpe 2)</span><b>Tecla X / Botão Leste</b></div>\r\n            <div class=\"key-row\"><span>Botão C (Soco Forte / Golpe 3)</span><b>Tecla A / Botão Oeste</b></div>\r\n            <div class=\"key-row\"><span>Botão D (Chute Forte / Especial)</span><b>Tecla S / Botão Norte</b></div>\r\n            <div class=\"key-row\"><span>🪙 Inserir Ficha (COIN)</span><b class=\"gold\">Tecla V / C / 5 / Select</b></div>\r\n            <div class=\"key-row\"><span>▶ Começar Jogo (1P START)</span><b class=\"green\">Enter / 1 / Start</b></div>\r\n            <div class=\"key-row\"><span>Alavanca / Direcional</span><b>Setas ⬆️⬇️⬅️➡️ / D-Pad</b></div>\r\n            <div class=\"key-row\"><span>📱 No Celular</span><b>Botões Touch na Tela</b></div>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"guide-card\">\r\n          <h3>💡 Dicas para Jogar no Fliperama</h3>\r\n          <p style=\"color:var(--muted);font-size:13.5px;line-height:1.6;margin:0 0 12px\">\r\n            Como nos fliperamas reais dos anos 90, os jogos do Neo Geo precisam de <b>Ficha</b> para começar:\r\n          </p>\r\n          <ol style=\"color:var(--ink);font-size:13.5px;line-height:1.7;padding-left:18px;margin:0\">\r\n            <li>Assim que o jogo abrir, aperte <b>V</b>, <b>C</b> ou <b>5</b> no teclado (ou toque em <b>🪙 FICHA</b> no celular) para colocar créditos.</li>\r\n            <li>Em seguida, aperte <b>Enter</b> ou toque em <b>▶ START</b> para iniciar a partida!</li>\r\n            <li>No celular, use os botões virtuais coloridos <b>A, B, C, D</b> na parte inferior da tela para desferir golpes e combos.</li>\r\n          </ol>\r\n        </div>\r\n      </div>\r\n    </section>\r\n  </main>\r\n\r\n  <footer class=\"footer\">\r\n    <span>NEO GEO MVS/AES ARCADE NO NAVEGADOR • <b>CONTINUE?</b></span>\r\n    <span>SNES • PS1 • NEO GEO • NINTENDO 64 • 2026</span>\r\n  </footer>\r\n</div>\r\n\r\n<script>\r\nconst FAV_KEY = 'continue_favorites_v1';\r\nconst grid = document.querySelector('#grid');\r\nconst arcadeShowcase = document.querySelector('#arcade-showcase');\r\nconst search = document.querySelector('#search');\r\nconst searchTop = document.querySelector('#search-top');\r\nconst clearSearchTop = document.querySelector('#clear-search-top');\r\nconst count = document.querySelector('#count');\r\nconst player = document.querySelector('#player');\r\nconst frame = document.querySelector('#game-frame');\r\nconst letters = document.querySelector('#letters');\r\nconst genreTabs = document.querySelector('#genre-tabs');\r\n\r\nlet roms = [];\r\nlet selectedLetter = 'Todos';\r\nlet selectedCategory = 'Todos';\r\nlet currentPlayingFile = null;\r\n\r\nconst descriptions = {\r\n  'kof2002': 'O ápice das batalhas em trio! Escolha Iori, Kyo, Rugal e dezenas de lutadores com jogabilidade rápida, cancelamentos MAX e combos espetaculares.',\r\n  'kof98': 'Considerado o torneio definitivo da SNK! Equilíbrio impecável entre os lutadores, trilha sonora inesquecível e combates clássicos da era de ouro.',\r\n  'mslugx': 'A versão definitiva e turbinada do clássico Metal Slug 2! Novas armas potentes, veículos alienígenas e muita ação explosiva com Marco e Tarma.',\r\n  'mslug3': 'A obra-prima dos tiroteios da SNK! Fases gigantes com rotas ramificadas, zumbis, submarinos, insetos mutantes e batalhas colossais.',\r\n  'samsho2': 'O mais aclamado duelo de espadas! Haohmaru, Genjuro, Nakoruru e Ukyo em combates táticos com armas afiadas e golpes fatais.',\r\n  'samsho4': 'Batalhas intensas com o sistema de Combo Fatal e escolha de estilo Corte (Slash) ou Busto (Bust) para cada guerreiro.',\r\n  'rbffspec': 'O auge da série Fatal Fury! Terry Bogard, Mai Shiranui e Geese Howard com cenários de múltiplos planos e golpes devastadores.',\r\n  'wjammers': 'O esporte arcade mais eletrizante do Neo Geo! Lance o disco em curvas impossíveis, use super poderes e marque gols contra seu rival.',\r\n  'turfmast': 'O melhor jogo de golfe de todos os tempos! Controles precisos, vento realista e partidas emocionantes que conquistaram os fliperamas.',\r\n  'sengoku3': 'Incrível beat \\x27em up ninja com combos longos, espadas afiadas, magias ancestrais e gráficos impressionantes.',\r\n  'blazstar': 'Shoot \\x27em up espacial com gráficos pré-renderizados lendários, tiros carregados e multiplicadores de pontuação viciantes.',\r\n  'shocktro': 'Ação tática com visão de cima! Escolha seu esquadrão mercenário, role para desviar de balas e destrua bases inimigas com lança-granadas.'\r\n};\r\n\r\nfunction getFavorites() {\r\n  try { return JSON.parse(localStorage.getItem(FAV_KEY) || '[]'); } catch { return []; }\r\n}\r\n\r\nfunction toggleFavorite(name) {\r\n  const favs = getFavorites();\r\n  const idx = favs.indexOf(name);\r\n  if (idx >= 0) favs.splice(idx, 1);\r\n  else favs.unshift(name);\r\n  try { localStorage.setItem(FAV_KEY, JSON.stringify(favs)); } catch {}\r\n  updateFavCount();\r\n  renderShowcase();\r\n  renderGenreTabs();\r\n  render();\r\n  syncDockFavButton();\r\n}\r\n\r\nfunction updateFavCount() {\r\n  const el = document.querySelector('#fav-nav-count');\r\n  if (el) el.textContent = getFavorites().length;\r\n}\r\n\r\nfunction cleanName(fileOrName) {\r\n  if (typeof fileOrName === 'object' && fileOrName !== null) {\r\n    if (fileOrName.title) return fileOrName.title;\r\n    fileOrName = fileOrName.name || '';\r\n  }\r\n  return String(fileOrName)\r\n    .replace(/\\.zip$/i, '')\r\n    .trim();\r\n}\r\n\r\nfunction firstLetter(file) {\r\n  const l = cleanName(file).normalize('NFD').replace(/[\\u0300-\\u036f]/g, '').charAt(0).toLocaleUpperCase('pt-BR');\r\n  return /^[A-Z]$/.test(l) ? l : '#';\r\n}\r\n\r\nfunction escapeHtml(s) {\r\n  return String(s).replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\r\n}\r\n\r\nfunction getGameDescription(f) {\r\n  const lower = ((f.name || '') + ' ' + (f.title || '')).toLowerCase();\r\n  if (lower.includes('kof2002') || (lower.includes('king of fighters') && lower.includes('2002'))) return descriptions.kof2002;\r\n  if (lower.includes('kof98') || (lower.includes('king of fighters') && lower.includes('98'))) return descriptions.kof98;\r\n  if (lower.includes('mslugx') || lower.includes('metal slug x')) return descriptions.mslugx;\r\n  if (lower.includes('mslug3') || lower.includes('metal slug 3')) return descriptions.mslug3;\r\n  if (lower.includes('samsho2') || (lower.includes('samurai') && lower.includes('ii'))) return descriptions.samsho2;\r\n  if (lower.includes('samsho4') || (lower.includes('samurai') && lower.includes('iv'))) return descriptions.samsho4;\r\n  if (lower.includes('rbffspec') || lower.includes('real bout') && lower.includes('special')) return descriptions.rbffspec;\r\n  if (lower.includes('wjammers') || lower.includes('windjammers')) return descriptions.wjammers;\r\n  if (lower.includes('turfmast') || lower.includes('turf masters')) return descriptions.turfmast;\r\n  if (lower.includes('sengoku3') || lower.includes('sengoku 3')) return descriptions.sengoku3;\r\n  if (lower.includes('blazstar') || lower.includes('blazing star')) return descriptions.blazstar;\r\n  if (lower.includes('shocktro') && !lower.includes('shocktr2')) return descriptions.shocktro;\r\n  return 'Lendário clássico de fliperama Neo Geo MVS/AES pronto para jogar direto no navegador!';\r\n}\r\n\r\n// Ordem dos 12 Destaques Top de Linha na Seção A\r\nconst SHOWCASE_KEYS = [\r\n  'kof2002',\r\n  'mslugx',\r\n  'kof98',\r\n  'mslug3',\r\n  'samsho2',\r\n  'wjammers',\r\n  'rbffspec',\r\n  'turfmast',\r\n  'blazstar',\r\n  'sengoku3',\r\n  'shocktro',\r\n  'samsho4'\r\n];\r\n\r\nfunction renderShowcase() {\r\n  if (!roms.length) {\r\n    arcadeShowcase.innerHTML = '';\r\n    return;\r\n  }\r\n  const favs = getFavorites();\r\n  const showcaseRoms = [];\r\n\r\n  SHOWCASE_KEYS.forEach(key => {\r\n    const found = roms.find(r => (r.name || '').toLowerCase().startsWith(key) && !showcaseRoms.includes(r));\r\n    if (found) showcaseRoms.push(found);\r\n  });\r\n\r\n  roms.forEach(r => {\r\n    if (showcaseRoms.length < 12 && r.featured && !showcaseRoms.includes(r)) {\r\n      showcaseRoms.push(r);\r\n    }\r\n  });\r\n\r\n  arcadeShowcase.innerHTML = showcaseRoms.map(f => {\r\n    const idx = roms.indexOf(f);\r\n    const title = cleanName(f);\r\n    const region = f.region || 'Arcade (MVS/AES)';\r\n    const genre = f.genre || 'Fliperama';\r\n    const isFav = favs.includes(f.name);\r\n    const cover = f.cover || '';\r\n\r\n    return `\r\n      <article class=\"arcade-card\">\r\n        <div class=\"arcade-art\" data-play-idx=\"${idx}\" title=\"Toque para jogar ${escapeHtml(title)}\">\r\n          ${cover ? `\r\n            <img class=\"arcade-art-img\" src=\"${escapeHtml(cover)}\" alt=\"Capa de ${escapeHtml(title)}\" loading=\"lazy\" decoding=\"async\">\r\n          ` : `<span class=\"art-fallback\">${escapeHtml(title)}</span>`}\r\n        </div>\r\n        <div class=\"arcade-body\">\r\n          <div>\r\n            <div class=\"arcade-badges\">\r\n              <span class=\"pill neogeo\">🕹️ NEO GEO</span>\r\n              <span class=\"pill gold\">★ 100 MEGA SHOCK</span>\r\n              <span class=\"pill\">${escapeHtml(genre)}</span>\r\n            </div>\r\n            <h3>${escapeHtml(title)}</h3>\r\n            <p>${escapeHtml(getGameDescription(f))}</p>\r\n          </div>\r\n          <div class=\"arcade-actions\">\r\n            <button class=\"btn-launch-neogeo\" type=\"button\" data-play-idx=\"${idx}\">Colocar Ficha & Jogar ▶</button>\r\n            <button class=\"dock-btn ${isFav ? 'active' : ''}\" type=\"button\" data-fav-name=\"${escapeHtml(f.name)}\" title=\"Favoritar\">★</button>\r\n          </div>\r\n        </div>\r\n      </article>\r\n    `;\r\n  }).join('');\r\n}\r\n\r\nfunction renderGenreTabs() {\r\n  const favSet = new Set(getFavorites());\r\n  const tabs = [\r\n    { id: 'Todos', label: `Todos (${roms.length})` },\r\n    { id: 'FEATURED', label: `★ Clássicos (${roms.filter(r => r.featured).length})` },\r\n    { id: 'FAV', label: `♥ Favoritos (${roms.filter(r => favSet.has(r.name)).length})` }\r\n  ];\r\n\r\n  const genres = [...new Set(roms.map(r => r.genre || 'Fliperama'))].sort();\r\n  genres.forEach(g => {\r\n    tabs.push({ id: g, label: `${g} (${roms.filter(r => (r.genre || 'Fliperama') === g).length})` });\r\n  });\r\n\r\n  genreTabs.innerHTML = tabs.map(t => `\r\n    <button class=\"genre-tab ${selectedCategory === t.id ? 'active' : ''}\" type=\"button\" data-cat=\"${escapeHtml(t.id)}\">\r\n      ${escapeHtml(t.label)}\r\n    </button>\r\n  `).join('');\r\n}\r\n\r\nfunction renderLetters() {\r\n  const counts = {};\r\n  roms.forEach(f => {\r\n    const l = firstLetter(f);\r\n    counts[l] = (counts[l] || 0) + 1;\r\n  });\r\n  letters.innerHTML = ['Todos', ...Object.keys(counts).sort((a, b) => a.localeCompare(b, 'pt-BR'))].map(l => `\r\n    <button class=\"letter ${selectedLetter === l ? 'active' : ''}\" type=\"button\" data-letter=\"${l}\">\r\n      ${l}${l === 'Todos' ? '' : ` · ${counts[l]}`}\r\n    </button>\r\n  `).join('');\r\n}\r\n\r\nfunction render() {\r\n  const q = search.value.trim().toLocaleLowerCase('pt-BR');\r\n  const favSet = new Set(getFavorites());\r\n\r\n  const shown = roms.filter(f => {\r\n    if (selectedLetter !== 'Todos' && firstLetter(f) !== selectedLetter) return false;\r\n    if (selectedCategory === 'FAV' && !favSet.has(f.name)) return false;\r\n    if (selectedCategory === 'FEATURED' && !f.featured) return false;\r\n    if (!['Todos', 'FAV', 'FEATURED'].includes(selectedCategory) && (f.genre || 'Fliperama') !== selectedCategory) return false;\r\n\r\n    if (q) {\r\n      const matchName = (f.name || '').toLocaleLowerCase('pt-BR').includes(q);\r\n      const matchTitle = (f.title || '').toLocaleLowerCase('pt-BR').includes(q);\r\n      const matchGenre = (f.genre || '').toLocaleLowerCase('pt-BR').includes(q);\r\n      if (!matchName && !matchTitle && !matchGenre) return false;\r\n    }\r\n    return true;\r\n  });\r\n\r\n  count.textContent = `${shown.length} de ${roms.length} jogos encontrados`;\r\n\r\n  grid.innerHTML = shown.length ? shown.map(f => {\r\n    const idx = roms.indexOf(f);\r\n    const title = cleanName(f);\r\n    const isFav = favSet.has(f.name);\r\n    const genre = f.genre || 'Fliperama';\r\n    const cover = f.cover || '';\r\n\r\n    return `\r\n      <article class=\"card\">\r\n        <div class=\"art\" data-play-idx=\"${idx}\" title=\"Toque para jogar ${escapeHtml(title)}\">\r\n          ${cover ? `\r\n            <img class=\"art-img\" src=\"${escapeHtml(cover)}\" alt=\"Capa de ${escapeHtml(title)}\" loading=\"lazy\" decoding=\"async\">\r\n          ` : `<span class=\"art-fallback\">${escapeHtml(title)}</span>`}\r\n          <div class=\"card-badges\">\r\n            ${f.featured ? '<span class=\"pill gold\">★ TOP</span>' : ''}\r\n            <span class=\"pill neogeo\">NEO GEO</span>\r\n          </div>\r\n          <button class=\"fav-btn ${isFav ? 'active' : ''}\" type=\"button\" data-fav-name=\"${escapeHtml(f.name)}\" title=\"Guardar nos Favoritos\">★</button>\r\n        </div>\r\n        <div class=\"info\">\r\n          <div>\r\n            <div class=\"title\">${escapeHtml(title)}</div>\r\n            <div class=\"raw-sub\">${escapeHtml(genre)}</div>\r\n          </div>\r\n          <div class=\"meta\">\r\n            <span>Arcade MVS</span>\r\n            <button class=\"play\" type=\"button\" data-play-idx=\"${idx}\">JOGAR ▶</button>\r\n          </div>\r\n        </div>\r\n      </article>\r\n    `;\r\n  }).join('') : '<div class=\"empty\">Nenhum jogo encontrado nessa busca ou filtro.</div>';\r\n}\r\n\r\nfunction syncDockFavButton() {\r\n  const btn = document.querySelector('#dock-fav');\r\n  if (!btn || !currentPlayingFile) return;\r\n  const isFav = getFavorites().includes(currentPlayingFile.name);\r\n  btn.classList.toggle('active', isFav);\r\n  btn.textContent = isFav ? '★ Favoritado' : '☆ Favoritar';\r\n}\r\n\r\nfunction start(file) {\r\n  if (!file) return;\r\n  currentPlayingFile = file;\r\n  const title = cleanName(file);\r\n  document.querySelector('#playing').textContent = title;\r\n  document.querySelector('#playing-meta').textContent = `// JOGANDO AGORA • NEO GEO (MVS/AES) • ${file.genre || 'FLIPERAMA'}`;\r\n  const thumb = document.querySelector('#playing-thumb');\r\n  if (file.cover) thumb.src = file.cover;\r\n\r\n  syncDockFavButton();\r\n  frame.src = 'neogeo-player.html?rom=' + encodeURIComponent(file.url) + '&title=' + encodeURIComponent(title);\r\n  player.classList.add('open');\r\n  player.scrollIntoView({ behavior: 'smooth', block: 'start' });\r\n}\r\n\r\n// Event Delegation para cliques nos jogos e botões\r\ndocument.addEventListener('click', (e) => {\r\n  const playTarget = e.target.closest('[data-play-idx]');\r\n  if (playTarget) {\r\n    const idx = parseInt(playTarget.dataset.playIdx, 10);\r\n    if (!isNaN(idx) && roms[idx]) {\r\n      start(roms[idx]);\r\n    }\r\n    return;\r\n  }\r\n\r\n  const favTarget = e.target.closest('[data-fav-name]');\r\n  if (favTarget) {\r\n    e.stopPropagation();\r\n    toggleFavorite(favTarget.dataset.favName);\r\n    return;\r\n  }\r\n\r\n  const letterTarget = e.target.closest('.letter');\r\n  if (letterTarget) {\r\n    selectedLetter = letterTarget.dataset.letter;\r\n    renderLetters();\r\n    render();\r\n    return;\r\n  }\r\n\r\n  const catTarget = e.target.closest('.genre-tab');\r\n  if (catTarget) {\r\n    selectedCategory = catTarget.dataset.cat;\r\n    renderGenreTabs();\r\n    render();\r\n    return;\r\n  }\r\n\r\n  const searchTag = e.target.closest('.search-tag');\r\n  if (searchTag) {\r\n    const term = searchTag.dataset.searchTerm;\r\n    if (term === 'Todos') {\r\n      search.value = '';\r\n      searchTop.value = '';\r\n      selectedCategory = 'Todos';\r\n      selectedLetter = 'Todos';\r\n    } else if (['Luta', 'Ação / Tiro', 'Esportes', 'Nave'].includes(term)) {\r\n      search.value = '';\r\n      searchTop.value = '';\r\n      selectedCategory = term === 'Nave' ? 'Nave / Tiro' : (term === 'Ação / Tiro' ? 'Ação / Tiro' : term);\r\n    } else {\r\n      search.value = term;\r\n      searchTop.value = term;\r\n      selectedCategory = 'Todos';\r\n      selectedLetter = 'Todos';\r\n    }\r\n    clearSearchTop.classList.toggle('visible', searchTop.value.length > 0);\r\n    renderLetters();\r\n    renderGenreTabs();\r\n    render();\r\n    return;\r\n  }\r\n});\r\n\r\n// Barra de busca superior e catálogo sincronizadas\r\nsearch.addEventListener('input', () => {\r\n  searchTop.value = search.value;\r\n  clearSearchTop.classList.toggle('visible', search.value.length > 0);\r\n  render();\r\n});\r\n\r\nsearchTop.addEventListener('input', () => {\r\n  search.value = searchTop.value;\r\n  clearSearchTop.classList.toggle('visible', searchTop.value.length > 0);\r\n  render();\r\n});\r\n\r\nclearSearchTop.addEventListener('click', () => {\r\n  search.value = '';\r\n  searchTop.value = '';\r\n  clearSearchTop.classList.remove('visible');\r\n  render();\r\n});\r\n\r\n// Botão Jogo Surpresa\r\ndocument.querySelector('#btn-random-neogeo').addEventListener('click', () => {\r\n  if (!roms.length) return;\r\n  const pick = roms[Math.floor(Math.random() * roms.length)];\r\n  start(pick);\r\n});\r\n\r\n// Controles do Player Dock\r\ndocument.querySelector('#close').addEventListener('click', () => {\r\n  frame.src = 'about:blank';\r\n  player.classList.remove('open');\r\n  currentPlayingFile = null;\r\n});\r\n\r\ndocument.querySelector('#dock-fullscreen').addEventListener('click', () => {\r\n  if (!frame) return;\r\n  if (frame.requestFullscreen) frame.requestFullscreen();\r\n  else if (frame.webkitRequestFullscreen) frame.webkitRequestFullscreen();\r\n});\r\n\r\ndocument.querySelector('#dock-fav').addEventListener('click', () => {\r\n  if (currentPlayingFile) toggleFavorite(currentPlayingFile.name);\r\n});\r\n\r\nasync function fetchNeoGeoCatalogWithFallback() {\r\n  try {\r\n    const res = await fetch('/api/neogeo', { cache: 'no-store' });\r\n    if (res.ok) {\r\n      const data = await res.json();\r\n      if (Array.isArray(data) && data.length) return data;\r\n    }\r\n  } catch {}\r\n  const fallback = await fetch('neogeo-games.json', { cache: 'no-store' });\r\n  if (!fallback.ok) throw new Error('Não consegui carregar o catálogo de Neo Geo.');\r\n  return await fallback.json();\r\n}\r\n\r\nasync function loadLibrary() {\r\n  updateFavCount();\r\n  try {\r\n    const payload = await fetchNeoGeoCatalogWithFallback();\r\n    roms = (Array.isArray(payload) ? payload : []).filter(item => item && typeof item.name === 'string' && typeof item.url === 'string');\r\n    roms.sort((a, b) => cleanName(a).localeCompare(cleanName(b), 'pt-BR'));\r\n    document.querySelector('#nav-neogeo-count').textContent = roms.length;\r\n\r\n    renderShowcase();\r\n    renderGenreTabs();\r\n    renderLetters();\r\n    render();\r\n\r\n    const params = new URLSearchParams(location.search);\r\n    const playParam = params.get('play');\r\n    if (playParam) {\r\n      const target = roms.find(r => r.name === playParam || cleanName(r).toLocaleLowerCase('pt-BR') === playParam.toLocaleLowerCase('pt-BR'));\r\n      if (target) start(target);\r\n    }\r\n  } catch (error) {\r\n    count.textContent = 'Erro ao carregar catálogo';\r\n    grid.innerHTML = `<div class=\"empty\">${escapeHtml(error.message)}</div>`;\r\n  }\r\n}\r\n\r\nloadLibrary();\r\n</script>\r\n</body>\r\n</html>";
